def monthly(journal, code):
    """`code`'s net change per calendar month: rows of ("YYYY-MM", cents),
    in month order, signed by the account's kind; months with no lines
    left out."""
    from .accounts import DEBIT_NORMAL

    sign = 1 if journal.chart.get(code).kind in DEBIT_NORMAL else -1
    months = {}
    for entry, line in journal.lines(code):
        key = entry.date.strftime("%Y-%m")
        months[key] = months.get(key, 0) + sign * line.cents
    return sorted(months.items())


